function makeUi(values: readonly string[]): NozzleFlowRateCalculatorUI {
  const locale = (Object.entries(UI_VALUES).find(([, localized]) => localized === values)?.[0] ?? 'de') as LocalizedLocale;
  const localized = {} as Record<UiKey, string>;
  UI_KEYS.forEach((key, index) => { localized[key] = values[index] ?? ''; });
  return {
    ...localized,
    ...EXTRA_UI_VALUES[locale],
    nozzleUnit: 'mm',
    lineWidthUnit: 'mm',
    layerHeightUnit: 'mm',
    speedUnit: 'mm/s',
    flowUnit: 'mm³/s',
  };
}

